#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using PVZEngine;
using PVZEngine.Entities;
using PVZEngine.Tools;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    public class PrismPylonProjectileModeRed : PrismPylonProjectileMode
    {
        public override NamespaceID GetModeBuffID()
        {
            return VanillaBuffID.Projectile.prismPylonProjectileRed;
        }
        public override void Apply(Entity entity, NamespaceID projectileID, Entity oldProjectile, Vector3 position, Vector3 velocity)
        {
            for (int i = 0; i < 2; i++)
            {
                var offsetMultiplier = (i * 2 - 1);
                var pos = GetSplitProjectilePosition(position, velocity, offsetMultiplier);
                ReplaceProjectile(entity, projectileID, oldProjectile, pos, velocity);
            }
            oldProjectile.Remove();
        }
        public override void ApplyToLight(Entity prism, List<Entity> projectiles)
        {
            base.ApplyToLight(prism, projectiles);
            using var newProjectilesItem = ListPool<Entity>.Rent();
            var newProjectiles = newProjectilesItem.Value;
            foreach (var projectile in projectiles)
            {
                var position = projectile.Position;
                var velocity = projectile.Velocity;

                var oldPos = GetSplitProjectilePosition(position, velocity, -1);
                projectile.Position = oldPos;

                var pos = GetSplitProjectilePosition(position, velocity, 1);
                var newProj = CloneProjectile(prism, projectile.GetDefinitionID(), projectile, pos, velocity);
                if (newProj != null)
                {
                    newProjectiles.Add(newProj);
                }
            }
            projectiles.AddRange(newProjectiles);
        }
        public static Vector3 GetSplitProjectilePosition(Vector3 position, Vector3 velocity, float multiplier)
        {
            var vel = velocity;
            var vel2D = new Vector2(vel.x, vel.z).normalized;
            var offset2DNorm = vel2D.RotateClockwise(90);
            var newHoriOffset = HORI_OFFSET * multiplier;
            var newOffset2D = offset2DNorm * newHoriOffset;
            var newPos = position;
            newPos.x += newOffset2D.x;
            newPos.z += newOffset2D.y;
            return newPos;
        }
        public const float HORI_OFFSET = 10;
    }
}
